CREATE TABLE dsa_problems (id BIGSERIAL PRIMARY KEY,title VARCHAR(255) NOT NULL CHECK(btrim(title)<>''),platform VARCHAR(80) NOT NULL,difficulty VARCHAR(10) NOT NULL CHECK(difficulty IN ('EASY','MEDIUM','HARD')),topic VARCHAR(100) NOT NULL,status VARCHAR(20) NOT NULL CHECK(status IN ('NOT_STARTED','IN_PROGRESS','SOLVED')),time_taken_minutes INTEGER NOT NULL DEFAULT 0 CHECK(time_taken_minutes>=0),revision_status VARCHAR(20) NOT NULL CHECK(revision_status IN ('NOT_REVIEWED','REVIEW_NEEDED','REVIEWED')),notes TEXT,solved_at DATE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE INDEX idx_dsa_problems_solved_at ON dsa_problems(solved_at DESC); CREATE INDEX idx_dsa_problems_topic ON dsa_problems(topic);
